// SQLite proof runs off main after the acknowledged worker barrier. It never writes.
async function readonlySqlite(file){
 const worker=new Worker(`const {parentPort,workerData}=require('node:worker_threads');const {DatabaseSync}=require('node:sqlite');let db;try{db=new DatabaseSync(workerData,{readOnly:true});parentPort.postMessage({value:db.prepare('SELECT value FROM state WHERE id=1').get().value});}catch(error){parentPort.postMessage({error:error.message});}finally{db?.close();parentPort.close();}`,{eval:true,workerData:file});readWorkers.add(worker);
 try{return await new Promise((resolve,reject)=>{let delivered=false;worker.once('message',reply=>{delivered=true;reply.error?reject(Error(reply.error)):resolve(JSON.parse(reply.value));});worker.once('error',reject);worker.once('exit',code=>{if(!delivered)reject(Error('Read-only SQLite proof exited before its result: '+code));});});}finally{await worker.terminate();readWorkers.delete(worker);}
}
