function record(name,status,details){const item={name,status,...(details===undefined?{}:{details})};evidence.assertions.push(item);console.log('SUNNY_DECK_ASSERT '+JSON.stringify(item));writeEvidence();}
async function check(name,run){activePhase=name;try{const details=await run();record(name,'pass',details);return true;}catch(error){record(name,'fail',error.stack||String(error));return false;}}
