 await check('keyboard-open-return',async()=>{await js(`(()=>{const e=document.querySelector('.work-entry[data-id="${missionId}"]');e.scrollIntoView({block:'center'});e.focus();})()`);await enterKey();await wait('Boolean(document.querySelector(".captain-review-mission"))');await until(()=>hub.state.workspace.context?.missionId===missionId,'keyboard selected mission');await click('.captain-open-result');await wait('Boolean(document.querySelector(".embedded-workbench"))');assert.equal(await js('Boolean(document.querySelector(".captain-log"))'),true);await click('[aria-label="Back to workspace"]');await wait('!document.querySelector(".embedded-workbench")');await until(()=>hub.state.workspace.context?.surface==='deck','return to deck');assert.equal(hub.state.workspace.context.missionId,missionId);await wait('document.activeElement.classList.contains("captain-open-result")||document.activeElement.classList.contains("captain-review-mission")');await screenshot('keyboard-open-return');});
 await check('selected-reply-display',async()=>{await wait('Boolean(document.querySelector(".captain-selected-result pre"))');assert.match(await js('document.querySelector(".captain-selected-result pre").textContent'),/SYNTHETIC captain result/);assert.equal(await js('Boolean(document.querySelector(".captain-log-status[role=status]"))'),true);await screenshot('selected-reply');});
 await check('no-second-task-on-reload',async()=>{const before=hub.state.tasks.length,calls=evidence.providerCalls.filter(c=>c.method==='turn/start').length;await reload();await delay(300);assert.equal(hub.state.tasks.length,before);assert.equal(evidence.providerCalls.filter(c=>c.method==='turn/start').length,calls);});
