async function fullHistoryJourney(){
 await check('paged-unicode-history-survives-valid-append-and-navigation',async()=>{
  const task=await hub.start({projectId:'fixture',crewId:'franky',title:'SYNTHETIC paged Unicode history',prompt:'Bounded history fixture; no external process'});
  const marker='SYNTHETIC OLDER HISTORY MARKER 🧭',messageId='synthetic-giant-history',unit='🧭航海é\n';
  const original='SYNTHETIC GIANT START\n'+unit.repeat(26000)+'SYNTHETIC GIANT END';
  const append='\nSYNTHETIC APPEND START\n'+unit.repeat(15000)+'SYNTHETIC APPEND END 🧭';
  assert.ok(Buffer.byteLength(original)>256*1024);assert.ok(Buffer.byteLength(append)<256*1024);
  await hub.notification({method:'item/completed',params:{threadId:task.threadId,item:{id:'synthetic-older-history',type:'agentMessage',text:marker}}});
  await hub.notification({method:'item/completed',params:{threadId:task.threadId,item:{id:messageId,type:'agentMessage',text:original}}});await hub.persist();
  const stateExpression=`(()=>{const nodes=Array.from(document.querySelectorAll('.embedded-workbench .conversation article[data-message-id]'));return {marker:nodes.some(node=>node.querySelector('.message-text').textContent===${JSON.stringify(marker)}),signature:nodes.map(node=>node.dataset.messageId+':'+node.dataset.messageOffset+':'+node.querySelector('.message-text').textContent.length).join('|'),segments:nodes.length,bytes:nodes.reduce((sum,node)=>sum+new TextEncoder().encode(node.querySelector('.message-text').textContent).length,0)};})()`;
  const inspect=()=>js(stateExpression);
  const open=async()=>{await wait(`Boolean(document.querySelector('.work-entry[data-id="${task.id}"]'))`);await click(`.work-entry[data-id="${task.id}"]`);await wait('Boolean(document.querySelector(".embedded-workbench .conversation article[data-message-id]"))');};
  const pageControl=async label=>{const before=(await inspect()).signature;await clickText(label);await wait(`(${stateExpression}).signature!==${JSON.stringify(before)}&&!document.querySelector('.embedded-workbench .conversation p[role="status"]')`);};
  const readOlder=async()=>{for(let page=0;page<4&&!(await inspect()).marker;page++)await pageControl('Load older history');assert.equal((await inspect()).marker,true,'Older marker is reachable through actual bounded history controls');};
  const bounded=async()=>{const view=await inspect();assert.ok(view.segments<=300,'At most 100 segments per page across three cached pages');assert.ok(view.bytes<=3*256*1024,'Displayed history remains bounded to three page byte limits');return view;};
  await open();await readOlder();await bounded();
  await hub.notification({method:'item/agentMessage/delta',params:{threadId:task.threadId,itemId:messageId,delta:append}});await hub.persist();
  await wait(`Array.from(document.querySelectorAll('.embedded-workbench .conversation button')).some(button=>button.textContent==='Load newer history'&&!button.disabled)`);
  assert.equal((await inspect()).marker,true,'A valid overflowing tail append retains older readable history');await bounded();
  await pageControl('Load newer history');await wait('document.querySelector(".embedded-workbench .conversation").textContent.includes("SYNTHETIC APPEND END 🧭")');
  const exactDisplayed=async()=>{const displayed=await js(`(async()=>{const parts=Array.from(document.querySelectorAll('.embedded-workbench .conversation article[data-message-id]')).filter(node=>node.dataset.messageId===${JSON.stringify(messageId)}).map(node=>({offset:Number(node.dataset.messageOffset),text:node.querySelector('.message-text').textContent})).sort((a,b)=>a.offset-b.offset);let length=0;for(const part of parts){if(part.offset!==length)throw Error('Displayed giant history has a missing or overlapping range');length+=part.text.length;}const bytes=new TextEncoder().encode(parts.map(part=>part.text).join(''));const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),byte=>byte.toString(16).padStart(2,'0')).join('');return {length,hash,segments:parts.length};})()`);assert.equal(displayed.length,(original+append).length);assert.equal(displayed.hash,sha(original+append));return displayed;};
  const first=await exactDisplayed();await bounded();
  await click('[aria-label="Back to workspace"]');await wait('!document.querySelector(".embedded-workbench")');await open();await readOlder();const afterNavigation=await exactDisplayed();const finalView=await bounded();
  // Independently reconstruct the complete backend history through bounded pages,
  // hashing segments incrementally. This does not require unbounded history in DOM.
  const summary=hub.fixtureTransport.taskReply(task),digest=createHash('sha256');let cursor,offset=0,pages=0,foundMarker=false;
  do{const page=hub.fixtureTransport.page({projectId:'fixture',taskId:task.id,epoch:hub.fixtureTransport.producer.epoch,revision:summary.transcriptRevision,direction:'newer',...(cursor?{cursor}:{})});assert.equal(page.stale,undefined);assert.ok(page.segments.length<=100);assert.ok(page.segments.reduce((sum,segment)=>sum+Buffer.byteLength(segment.text),0)<=256*1024);for(const segment of page.segments){if(segment.text===marker)foundMarker=true;if(segment.messageId===messageId){assert.equal(segment.offset,offset);offset+=segment.text.length;digest.update(segment.text,'utf8');}}cursor=page.nextCursor;pages++;assert.ok(pages<=4,'This bounded fixture needs no more than four pages');}while(cursor);
  assert.equal(foundMarker,true);assert.equal(offset,(original+append).length);assert.equal(digest.digest('hex'),sha(original+append));await complete(task,'SYNTHETIC full-history traversal completed.');await screenshot('paged-unicode-history');await click('[aria-label="Back to workspace"]');
  return {synthetic:true,olderMarkerRetained:true,validAppendBytes:Buffer.byteLength(append),backendPages:pages,exactTextSha256:sha(original+append),first,afterNavigation,finalView,scope:'Bounded supplied history traversal; production page controls, hooks and exact backend reconstruction. No claim that arbitrary full history is simultaneously mounted.'};
 });
}

